dsl.css:
.home-page {
  min-height: 100vh;
  background: var(--bg);
}

/* ---------- ① 页面标题区 ---------- */
.page-header {
  padding: 32rpx 32rpx 16rpx;
  display: flex;
  flex-direction: column;
}

.header-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.header-left {
  display: flex;
  flex-direction: column;
}

.header-title {
  font-size: 48rpx;
  font-weight: 700;
  color: var(--text-1);
}

.header-date {
  margin-top: 8rpx;
  font-size: 28rpx;
  color: var(--text-2);
}

.header-sub {
  margin-top: 12rpx;
  font-size: 30rpx;
  color: var(--primary);
}

.reminder-btn {
  display: flex;
  align-items: center;
  gap: 8rpx;
  padding: 14rpx 22rpx;
  border-radius: 24rpx;
  background: rgba(125, 116, 107, 0.1);
}

.reminder-btn.on {
  background: rgba(143, 166, 142, 0.2);
}

.reminder-icon {
  font-size: 34rpx;
  line-height: 1;
}

.reminder-text {
  font-size: 24rpx;
  font-weight: 500;
  color: var(--text-2);
}

.reminder-btn.on .reminder-text {
  color: var(--primary);
}

/* ---------- 卡片通用 ---------- */
.card-block {
  padding: 0 32rpx;
  margin-bottom: 28rpx;
}

.card-heading {
  font-size: 36rpx;
  font-weight: 600;
  color: var(--text-1);
}

.card-heading.small {
  font-size: 32rpx;
}

.card-header-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 24rpx;
}

.link-more {
  font-size: 26rpx;
  font-weight: 500;
  color: var(--primary);
}

/* ---------- ② 快捷打卡 ---------- */
.checkin-row {
  display: flex;
  gap: 24rpx;
  margin-top: 24rpx;
}

.checkin-card {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10rpx;
  padding: 32rpx 16rpx;
  background: rgba(125, 116, 107, 0.06);
  border: 4rpx solid transparent;
  border-radius: 28rpx;
  transition: all 0.25s ease;
}

.checkin-card.sleeping {
  background: rgba(143, 166, 142, 0.2);
  border-color: var(--primary);
}

.checkin-card.woken {
  background: rgba(212, 165, 116, 0.2);
  border-color: var(--warning);
}

.checkin-card.disabled {
  opacity: 0.5;
}

.checkin-card:active {
  transform: scale(0.98);
}

.checkin-emoji {
  font-size: 64rpx;
  line-height: 1.1;
  opacity: 0.6;
}

.checkin-emoji.active,
.checkin-emoji.warn {
  opacity: 1;
}

.checkin-name {
  font-size: 34rpx;
  font-weight: 600;
  color: var(--text-1);
}

.checkin-desc {
  font-size: 26rpx;
  color: var(--text-2);
}

.round-btn {
  width: 100%;
  margin-top: 24rpx;
  padding: 24rpx 0;
  background: var(--primary);
  border-radius: 24rpx;
  font-size: 32rpx;
  font-weight: 600;
  color: #ffffff;
  text-align: center;
}

.round-btn:active {
  opacity: 0.9;
  transform: scale(0.98);
}

/* ---------- ③ 打卡记录 ---------- */
.empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10rpx;
  padding: 64rpx 0;
}

.empty-icon {
  font-size: 96rpx;
  opacity: 0.35;
}

.empty-text {
  font-size: 30rpx;
  color: var(--text-1);
}

.empty-hint {
  font-size: 26rpx;
  color: var(--text-2);
}

.record-list {
  display: flex;
  flex-direction: column;
  gap: 20rpx;
}

.record-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 24rpx;
  background: rgba(125, 116, 107, 0.05);
  border-radius: 24rpx;
}

.record-left {
  display: flex;
  align-items: center;
  gap: 20rpx;
}

.record-avatar {
  width: 72rpx;
  height: 72rpx;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 36rpx;
  background: rgba(143, 166, 142, 0.2);
  border-radius: 50%;
}

.record-info {
  display: flex;
  flex-direction: column;
  gap: 4rpx;
}

.record-date {
  font-size: 30rpx;
  font-weight: 600;
  color: var(--text-1);
}

.record-time {
  font-size: 26rpx;
  color: var(--text-2);
}

.record-right {
  display: flex;
  align-items: center;
  gap: 16rpx;
}

.record-wake {
  font-size: 26rpx;
  color: var(--text-2);
}

.pill {
  padding: 6rpx 20rpx;
  border-radius: 999rpx;
  font-size: 22rpx;
  font-weight: 600;
  white-space: nowrap;
}

.pill-success {
  background: rgba(143, 166, 142, 0.2);
  color: var(--primary-d);
}

.pill-warning {
  background: rgba(212, 165, 116, 0.2);
  color: var(--warning);
}

/* ---------- ④ 睡眠评分环 ---------- */
.score-card {
  position: relative;
  overflow: hidden;
}

.deco {
  position: absolute;
  opacity: 0.1;
}

.deco-moon {
  top: 8rpx;
  right: 24rpx;
  font-size: 140rpx;
}

.deco-sparkles {
  bottom: 8rpx;
  left: 16rpx;
  font-size: 110rpx;
}

.score-tag {
  padding: 8rpx 20rpx;
  font-size: 26rpx;
  color: var(--primary-d);
  background: rgba(143, 166, 142, 0.15);
  border-radius: 999rpx;
}

.score-body {
  display: flex;
  align-items: center;
}

/* 纯 CSS 评分环：外层 conic-gradient 进度弧，内层挖空 */
.score-ring {
  position: relative;
  width: 240rpx;
  height: 240rpx;
  flex-shrink: 0;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.4s ease;
}

.ring-inner {
  width: 176rpx;
  height: 176rpx;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  background: #ffffff;
  border-radius: 50%;
  box-shadow: inset 0 4rpx 16rpx rgba(0, 0, 0, 0.06);
}

.score-num {
  font-size: 60rpx;
  font-weight: 700;
  color: var(--primary-d);
  line-height: 1.1;
}

.score-unit {
  font-size: 24rpx;
  color: var(--text-2);
}

.score-detail {
  flex: 1;
  margin-left: 36rpx;
  display: flex;
  flex-direction: column;
  gap: 20rpx;
}

.detail-row {
  display: flex;
  flex-direction: column;
  gap: 4rpx;
}

.detail-label {
  font-size: 24rpx;
  color: var(--text-2);
}

.detail-value {
  font-size: 30rpx;
  font-weight: 600;
  color: var(--text-1);
}

.detail-value.primary {
  color: var(--primary-d);
}

/* ---------- ⑤ 天气卡片 ---------- */
.weather-card {
  background: linear-gradient(135deg, #eef6ff 0%, #e2f0fb 100%);
}

.weather-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.weather-left {
  display: flex;
  align-items: center;
  gap: 20rpx;
}

.weather-emoji {
  font-size: 68rpx;
  line-height: 1;
}

.weather-text {
  display: flex;
  flex-direction: column;
  gap: 4rpx;
}

.weather-name {
  font-size: 38rpx;
  font-weight: 700;
  color: var(--text-1);
}

.weather-wind {
  font-size: 26rpx;
  color: var(--text-2);
}

.weather-right {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
}

.weather-temp {
  font-size: 58rpx;
  font-weight: 700;
  color: var(--warning);
  line-height: 1.1;
}

.weather-humidity {
  font-size: 26rpx;
  color: var(--text-2);
}

.weather-footer {
  display: block;
  margin-top: 20rpx;
  padding-top: 20rpx;
  border-top: 2rpx solid rgba(125, 116, 107, 0.15);
  font-size: 26rpx;
  color: var(--text-2);
}

/* ---------- ⑥ 本周日历 ---------- */
.week-row {
  display: flex;
  justify-content: space-between;
  margin-top: 24rpx;
}

.week-day {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10rpx;
}

.week-label {
  font-size: 22rpx;
  color: var(--text-2);
}

.week-date {
  width: 72rpx;
  height: 72rpx;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 28rpx;
  font-weight: 600;
  color: var(--text-1);
  background: rgba(125, 116, 107, 0.06);
  border-radius: 50%;
}

.week-date.today {
  background: var(--primary);
  color: #ffffff;
}

.week-date.recorded {
  background: rgba(143, 166, 142, 0.2);
  color: var(--primary-d);
}

.week-check {
  font-size: 22rpx;
  color: var(--primary);
}

/* ---------- ⑦ 今日活动 ---------- */
.activity-grid {
  display: flex;
  margin-top: 24rpx;
  margin-bottom: 28rpx;
}

.activity-cell {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6rpx;
}

.activity-emoji {
  font-size: 40rpx;
  line-height: 1;
}

.activity-value {
  font-size: 36rpx;
  font-weight: 700;
  color: var(--text-1);
}

.activity-unit {
  font-size: 22rpx;
  color: var(--text-2);
}

.activity-goal {
  padding-top: 20rpx;
  border-top: 2rpx solid var(--divider);
}

.goal-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 14rpx;
}

.goal-label {
  font-size: 26rpx;
  color: var(--text-2);
}

.goal-percent {
  font-size: 26rpx;
  font-weight: 600;
  color: var(--primary-d);
}

.progress-track {
  width: 100%;
  height: 16rpx;
  background: rgba(125, 116, 107, 0.12);
  border-radius: 8rpx;
  overflow: hidden;
}

.progress-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--primary), #9db89c);
  border-radius: 8rpx;
  transition: width 0.4s ease;
}

/* ---------- ⑧ 用药提醒 ---------- */
.medicine-list {
  display: flex;
  flex-direction: column;
  gap: 20rpx;
}

.medicine-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 24rpx;
  background: rgba(125, 116, 107, 0.05);
  border-radius: 24rpx;
}

.medicine-info {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 6rpx;
}

.medicine-name-row {
  display: flex;
  align-items: center;
  gap: 16rpx;
}

.medicine-name {
  font-size: 32rpx;
  font-weight: 600;
  color: var(--text-1);
}

.medicine-desc,
.medicine-time {
  font-size: 26rpx;
  color: var(--text-2);
}

.medicine-check {
  width: 72rpx;
  height: 72rpx;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 36rpx;
  color: var(--text-3);
  background: rgba(125, 116, 107, 0.08);
  border-radius: 50%;
}

.medicine-check.taken {
  background: var(--primary);
  color: #ffffff;
}

/* ---------- ⑨ AI 分析 ---------- */
.ai-conclusion {
  display: flex;
  align-items: flex-start;
  gap: 20rpx;
  padding: 24rpx;
  background: rgba(143, 166, 142, 0.1);
  border-radius: 24rpx;
}

.ai-emoji {
  font-size: 40rpx;
  line-height: 1.2;
}

.ai-text {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 8rpx;
}

.ai-main {
  font-size: 30rpx;
  font-weight: 600;
  color: var(--text-1);
  line-height: 1.6;
}

.ai-sub {
  font-size: 26rpx;
  color: var(--text-2);
  line-height: 1.6;
}

.ai-report-btn {
  margin-top: 28rpx;
  padding: 26rpx 0;
  background: linear-gradient(135deg, var(--primary), #9db89c);
  border-radius: 24rpx;
  font-size: 30rpx;
  font-weight: 600;
  color: #ffffff;
  text-align: center;
}

.ai-report-btn:active {
  opacity: 0.9;
}

/* ---------- 弹窗 ---------- */
.dialog-mask {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 100;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 64rpx;
  background: rgba(0, 0, 0, 0.45);
}

.dialog-box {
  width: 100%;
  padding: 40rpx;
  background: var(--surface);
  border-radius: 32rpx;
  display: flex;
  flex-direction: column;
}

.dialog-header-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 16rpx;
}

.dialog-title {
  font-size: 36rpx;
  font-weight: 700;
  color: var(--text-1);
}

.dialog-close {
  font-size: 26rpx;
  color: var(--text-2);
}

.dialog-message {
  margin-top: 20rpx;
  font-size: 28rpx;
  line-height: 1.8;
  color: var(--text-2);
  white-space: pre-wrap;
}

.dialog-actions {
  display: flex;
  gap: 20rpx;
  margin-top: 40rpx;
}

.dialog-btn {
  flex: 1;
  padding: 24rpx 0;
  border-radius: 24rpx;
  font-size: 30rpx;
  font-weight: 600;
  text-align: center;
}

.dialog-btn.cancel {
  background: rgba(125, 116, 107, 0.1);
  color: var(--text-2);
}

.dialog-btn.confirm {
  background: var(--primary);
  color: #ffffff;
}

.switch-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 28rpx 0;
  border-bottom: 2rpx solid var(--divider);
}

.switch-label {
  font-size: 30rpx;
  color: var(--text-1);
}

.switch {
  width: 88rpx;
  height: 48rpx;
  padding: 4rpx;
  display: flex;
  align-items: center;
  background: rgba(125, 116, 107, 0.2);
  border-radius: 24rpx;
  transition: background 0.2s ease;
}

.switch.on {
  background: var(--primary);
}

.switch-knob {
  width: 40rpx;
  height: 40rpx;
  background: #ffffff;
  border-radius: 50%;
  transition: transform 0.2s ease;
}

.switch.on .switch-knob {
  transform: translateX(40rpx);
}

.reminder-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 24rpx 0;
  border-bottom: 2rpx solid var(--divider);
}

.reminder-label {
  font-size: 28rpx;
  color: var(--text-2);
}

.reminder-values {
  display: flex;
  align-items: center;
  gap: 12rpx;
}

.reminder-chip {
  padding: 6rpx 18rpx;
  font-size: 24rpx;
  color: var(--primary-d);
  background: var(--primary-l);
  border-radius: 999rpx;
}

.reminder-tip {
  font-size: 24rpx;
  color: var(--text-3);
}

.dialog-test-row {
  display: flex;
  gap: 20rpx;
  margin-top: 32rpx;
}

.dialog-test-btn {
  flex: 1;
  padding: 22rpx 0;
  background: rgba(143, 166, 142, 0.12);
  border-radius: 24rpx;
  font-size: 26rpx;
  color: var(--primary-d);
  text-align: center;
}

