.guardian-page {
  min-height: 100vh;
  padding: 32rpx;
  background: linear-gradient(180deg, #f4efe6 0%, #f5f0e6 100%);
}

/* ---------- ① 标题区 ---------- */
.page-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  margin-bottom: 32rpx;
}

.header-content {
  display: flex;
  flex-direction: column;
  gap: 6rpx;
}

.header-line {
  display: flex;
  align-items: center;
  gap: 14rpx;
}

.header-icon {
  font-size: 46rpx;
  line-height: 1;
}

.header-title {
  font-size: 48rpx;
  font-weight: 700;
  color: #2c3e2d;
}

.header-sub {
  font-size: 28rpx;
  color: var(--text-2);
}

.header-date {
  font-size: 26rpx;
  color: var(--text-2);
}

/* ---------- ② 安全指示灯 ---------- */
.safety-section {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 32rpx;
  margin-bottom: 28rpx;
  background: var(--surface);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
}

.safety-indicator {
  display: flex;
  align-items: center;
  gap: 20rpx;
}

.safety-led {
  position: relative;
  width: 56rpx;
  height: 56rpx;
  display: flex;
  align-items: center;
  justify-content: center;
}

.led-glow {
  position: absolute;
  width: 56rpx;
  height: 56rpx;
  border-radius: 50%;
  opacity: 0.35;
  animation: led-pulse 1.8s ease-in-out infinite;
}

.led-core {
  position: relative;
  width: 24rpx;
  height: 24rpx;
  border-radius: 50%;
}

.led-safe .led-glow, .glow-safe { background: var(--success); }
.core-safe { background: var(--success); }
.led-warning .led-glow, .glow-warning { background: var(--warning); }
.core-warning { background: var(--warning); }
.led-danger .led-glow, .glow-danger { background: var(--danger); }
.core-danger { background: var(--danger); }

@keyframes led-pulse {
  0%, 100% { transform: scale(1); opacity: 0.35; }
  50% { transform: scale(1.35); opacity: 0.15; }
}

.safety-label {
  font-size: 36rpx;
  font-weight: 700;
  color: var(--text-1);
}

.guardian-stats {
  display: flex;
  align-items: center;
  gap: 32rpx;
}

.stat-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4rpx;
}

.stat-value {
  font-size: 40rpx;
  font-weight: 700;
  color: var(--primary-d);
}

.stat-label {
  font-size: 24rpx;
  color: var(--text-2);
}

.stat-divider {
  width: 2rpx;
  height: 48rpx;
  background: var(--divider);
}

/* ---------- ③ 老人状态卡 ---------- */
.elder-card {
  display: flex;
  flex-direction: column;
  gap: 28rpx;
}

.elder-top {
  display: flex;
  align-items: center;
  gap: 24rpx;
}

.elder-avatar {
  width: 96rpx;
  height: 96rpx;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 40rpx;
  font-weight: 700;
  color: #ffffff;
  background: linear-gradient(135deg, var(--primary), #a8c4a7);
  border-radius: 50%;
}

.elder-main {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 8rpx;
}

.elder-name-row {
  display: flex;
  align-items: center;
  gap: 16rpx;
}

.elder-name {
  font-size: 38rpx;
  font-weight: 700;
  color: var(--text-1);
}

.status-tag {
  padding: 4rpx 18rpx;
  font-size: 22rpx;
  border-radius: 999rpx;
}

.status-tag.safe {
  background: var(--primary-l);
  color: var(--primary-d);
}

.status-tag.danger {
  background: var(--danger-l);
  color: var(--danger);
}

.elder-desc {
  font-size: 26rpx;
  color: var(--text-2);
}

.elder-metrics {
  display: flex;
  padding-top: 24rpx;
  border-top: 2rpx solid var(--divider);
}

.metric-cell {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8rpx;
}

.metric-value {
  font-size: 34rpx;
  font-weight: 700;
  color: var(--text-1);
}

.metric-value.danger {
  color: var(--danger);
}

.metric-label {
  font-size: 24rpx;
  color: var(--text-2);
}

/* ---------- ④ SOS 按钮 ---------- */
.sos-section {
  margin-bottom: 28rpx;
}

.sos-button {
  position: relative;
  width: 100%;
  height: 360rpx;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 16rpx;
  background: linear-gradient(135deg, #ff6b6b, #ee5a5a);
  border-radius: 48rpx;
  box-shadow: 0 16rpx 48rpx rgba(238, 90, 90, 0.3);
  overflow: hidden;
}

/* 扩散波纹 */
.sos-button::after {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  width: 200rpx;
  height: 200rpx;
  margin: -100rpx 0 0 -100rpx;
  border: 4rpx solid rgba(255, 255, 255, 0.3);
  border-radius: 50%;
  animation: sos-ripple 2.5s ease-out infinite;
}

@keyframes sos-ripple {
  0% { transform: scale(0.5); opacity: 1; }
  100% { transform: scale(3); opacity: 0; }
}

.sos-active {
  background: linear-gradient(135deg, #f5b041, #e85a5a);
}

.sos-progress-ring {
  position: absolute;
  top: 12rpx;
  left: 12rpx;
  right: 12rpx;
  bottom: 12rpx;
  border-radius: 40rpx;
  transition: background 0.1s linear;
}

.sos-icon {
  position: relative;
  z-index: 3;
  font-size: 72rpx;
  line-height: 1;
}

.sos-text {
  position: relative;
  z-index: 3;
  font-size: 68rpx;
  font-weight: 800;
  color: #ffffff;
  letter-spacing: 8rpx;
}

.sos-hint {
  position: relative;
  z-index: 3;
  font-size: 28rpx;
  color: rgba(255, 255, 255, 0.85);
}

.sos-countdown {
  position: relative;
  z-index: 3;
  font-size: 26rpx;
  color: rgba(255, 255, 255, 0.95);
  font-weight: 600;
}

.sos-status-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 20rpx;
  padding: 24rpx 28rpx;
  background: var(--surface);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
}

.sos-status-left {
  display: flex;
  align-items: center;
  gap: 14rpx;
}

.sos-status-icon {
  font-size: 34rpx;
}

.sos-status-text {
  font-size: 28rpx;
  color: var(--text-1);
}

.sos-resolve-btn {
  padding: 12rpx 28rpx;
  background: var(--danger-l);
  border-radius: 999rpx;
  font-size: 26rpx;
  color: var(--danger);
}

/* ---------- ⑤ 设备 ---------- */
.card-header-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 8rpx;
}

.section-title {
  font-size: 34rpx;
  font-weight: 700;
  color: var(--text-1);
}

.link-more {
  font-size: 26rpx;
  color: var(--primary);
}

.device-list {
  display: flex;
  flex-direction: column;
}

.device-item {
  display: flex;
  align-items: center;
  gap: 20rpx;
  padding: 24rpx 0;
  border-bottom: 2rpx solid var(--divider);
}

.device-item:last-child {
  border-bottom: none;
}

.device-icon-wrapper {
  width: 72rpx;
  height: 72rpx;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--primary-l);
  border-radius: 20rpx;
}

.device-emoji {
  font-size: 36rpx;
}

.device-info {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 6rpx;
}

.device-name {
  font-size: 30rpx;
  font-weight: 600;
  color: var(--text-1);
}

.device-sync {
  font-size: 24rpx;
  color: var(--text-2);
}

.device-right {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 6rpx;
}

.device-status {
  font-size: 26rpx;
  color: var(--primary-d);
}

.device-status.danger {
  color: var(--danger);
}

.device-battery {
  font-size: 24rpx;
  color: var(--text-2);
}

.device-battery.warn {
  color: var(--warning);
}

/* ---------- ⑥ 告警 ---------- */
.no-alerts {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12rpx;
  padding: 56rpx 0;
}

.no-alerts-icon {
  font-size: 64rpx;
  color: var(--primary);
}

.no-alerts-text {
  font-size: 28rpx;
  color: var(--text-2);
}

.alerts-list {
  display: flex;
  flex-direction: column;
  gap: 20rpx;
}

.alert-item {
  display: flex;
  gap: 20rpx;
  padding: 24rpx;
  border-radius: 24rpx;
  background: rgba(125, 116, 107, 0.05);
  border-left: 8rpx solid var(--warning);
}

.alert-critical, .alert-high {
  border-left-color: var(--danger);
  background: var(--danger-l);
}

.alert-medium {
  border-left-color: var(--warning);
  background: var(--warning-l);
}

.alert-low {
  border-left-color: var(--primary);
  background: var(--primary-l);
}

.alert-icon-wrapper {
  font-size: 40rpx;
  line-height: 1.2;
}

.alert-content {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 10rpx;
}

.alert-title-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.alert-title {
  font-size: 30rpx;
  font-weight: 600;
  color: var(--text-1);
}

.alert-time {
  font-size: 24rpx;
  color: var(--text-3);
}

.alert-message {
  font-size: 26rpx;
  color: var(--text-2);
  line-height: 1.6;
}

.alert-actions-row {
  display: flex;
  align-items: center;
  gap: 16rpx;
}

.alert-btn {
  padding: 12rpx 26rpx;
  border-radius: 999rpx;
  font-size: 24rpx;
  color: #ffffff;
  background: var(--warning);
}

.alert-btn.btn-urgent {
  background: var(--danger);
}

.alert-handled {
  font-size: 24rpx;
  color: var(--primary-d);
}

/* ---------- ⑦ 快捷操作 ---------- */
.quick-actions-grid {
  display: flex;
  margin-top: 24rpx;
}

.action-btn {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12rpx;
}

.action-icon-wrapper {
  width: 88rpx;
  height: 88rpx;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 40rpx;
  background: var(--primary-l);
  border-radius: 28rpx;
}

.action-label {
  font-size: 24rpx;
  color: var(--text-2);
}

/* ---------- 通用 ---------- */
.empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10rpx;
  padding: 56rpx 0;
}

.empty-icon {
  font-size: 80rpx;
  opacity: 0.4;
}

.empty-text {
  font-size: 28rpx;
  color: var(--text-1);
}

.empty-hint {
  font-size: 24rpx;
  color: var(--text-2);
}

.dialog-mask {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 100;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 64rpx;
  background: rgba(0, 0, 0, 0.45);
}

.dialog-box {
  width: 100%;
  padding: 40rpx;
  background: var(--surface);
  border-radius: 32rpx;
  display: flex;
  flex-direction: column;
}

.dialog-title {
  font-size: 36rpx;
  font-weight: 700;
  color: var(--text-1);
}

.dialog-message {
  margin-top: 20rpx;
  font-size: 28rpx;
  line-height: 1.8;
  color: var(--text-2);
}

.dialog-actions {
  display: flex;
  gap: 20rpx;
  margin-top: 40rpx;
}

.dialog-btn {
  flex: 1;
  padding: 24rpx 0;
  border-radius: 24rpx;
  font-size: 30rpx;
  font-weight: 600;
  text-align: center;
}

.dialog-btn.cancel {
  background: rgba(125, 116, 107, 0.1);
  color: var(--text-2);
}

.dialog-btn.confirm {
  background: var(--danger);
  color: #ffffff;
}

