dsl.css:
.monitor-page {
  min-height: 100vh;
  padding: 24rpx;
  background: linear-gradient(180deg, #f4efe6 0%, #f0f4f0 100%);
}

/* ---------- 大字模式开关条 ---------- */
.elder-mode-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 24rpx 28rpx;
  margin-bottom: 24rpx;
  background: rgba(143, 166, 142, 0.14);
  border-radius: var(--radius);
}

.elder-mode-left {
  display: flex;
  align-items: center;
  gap: 18rpx;
  flex: 1;
}

.elder-mode-icon {
  font-size: 40rpx;
}

.elder-mode-text {
  display: flex;
  flex-direction: column;
  gap: 4rpx;
}

.elder-mode-label {
  font-size: 32rpx;
  font-weight: 600;
  color: #2d3436;
}

.elder-mode-desc {
  font-size: 22rpx;
  color: var(--text-2);
}

.elder-switch {
  width: 96rpx;
  height: 52rpx;
  padding: 4rpx;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  background: rgba(125, 116, 107, 0.2);
  border-radius: 26rpx;
  transition: background 0.2s ease;
}

.elder-switch.on {
  background: var(--primary);
}

.elder-switch-knob {
  width: 44rpx;
  height: 44rpx;
  background: #ffffff;
  border-radius: 50%;
  transition: transform 0.2s ease;
}

.elder-switch.on .elder-switch-knob {
  transform: translateX(44rpx);
}

/* ---------- 模式 Tab ---------- */
.mode-tabs {
  display: flex;
  gap: 16rpx;
  margin-bottom: 24rpx;
}

.mode-tab {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8rpx;
  padding: 24rpx 0;
  background: var(--surface);
  border: 4rpx solid transparent;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
}

.mode-tab.active {
  background: rgba(143, 166, 142, 0.16);
  border-color: var(--primary);
}

.mode-tab-icon {
  font-size: 40rpx;
}

.mode-tab-label {
  font-size: 26rpx;
  color: var(--text-2);
}

.mode-tab.active .mode-tab-label {
  color: var(--primary-d);
  font-weight: 600;
}

/* ---------- 监测卡片 ---------- */
.monitor-card {
  display: flex;
  flex-direction: column;
}

.card-head {
  display: flex;
  align-items: center;
  gap: 20rpx;
  margin-bottom: 24rpx;
}

.card-icon-wrapper {
  width: 80rpx;
  height: 80rpx;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 38rpx;
  border-radius: 24rpx;
  background: var(--primary-l);
}

.card-head-text {
  display: flex;
  flex-direction: column;
  gap: 4rpx;
}

.card-title {
  font-size: 34rpx;
  font-weight: 600;
  color: var(--text-1);
}

.card-desc {
  font-size: 24rpx;
  color: var(--text-2);
}

/* ---------- 语音 ---------- */
.recording-status {
  padding: 28rpx;
  background: rgba(125, 116, 107, 0.05);
  border-radius: 24rpx;
  margin-bottom: 28rpx;
}

.recording-indicator {
  display: flex;
  align-items: center;
  gap: 16rpx;
}

.pulse-dot {
  width: 20rpx;
  height: 20rpx;
  background: var(--danger);
  border-radius: 50%;
  animation: dot-blink 1s ease-in-out infinite;
}

@keyframes dot-blink {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.4; transform: scale(0.8); }
}

.recording-text {
  font-size: 30rpx;
  font-weight: 600;
  color: var(--danger);
}

.voice-result {
  display: flex;
  flex-direction: column;
  gap: 8rpx;
}

.voice-result-label {
  font-size: 24rpx;
  color: var(--text-2);
}

.voice-text {
  font-size: 30rpx;
  color: var(--text-1);
  line-height: 1.6;
}

.recording-idle {
  font-size: 26rpx;
  color: var(--text-2);
}

.record-btn-wrapper {
  display: flex;
  justify-content: center;
  margin-bottom: 28rpx;
}

.record-btn {
  width: 240rpx;
  height: 240rpx;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10rpx;
  background: linear-gradient(135deg, var(--primary), #a8c4a7);
  border-radius: 50%;
  box-shadow: 0 16rpx 40rpx rgba(143, 166, 142, 0.3);
}

.record-btn.stop {
  background: linear-gradient(135deg, #ff6b6b, #ee5a5a);
  box-shadow: 0 16rpx 40rpx rgba(238, 90, 90, 0.3);
}

.record-btn:active {
  transform: scale(0.97);
}

.record-emoji {
  font-size: 64rpx;
  line-height: 1;
}

.record-label {
  font-size: 26rpx;
  color: #ffffff;
  font-weight: 600;
}

/* ---------- 手动输入 ---------- */
.manual-box {
  display: flex;
  flex-direction: column;
  gap: 16rpx;
}

.manual-label {
  font-size: 24rpx;
  color: var(--text-2);
}

.manual-input {
  padding: 24rpx 28rpx;
  background: rgba(255, 255, 255, 0.9);
  border: 2rpx solid var(--border);
  border-radius: 20rpx;
  font-size: 28rpx;
  color: var(--text-1);
}

.field-ph {
  color: var(--text-3);
}

.manual-btn {
  padding: 24rpx 0;
  background: var(--primary);
  border-radius: 20rpx;
  font-size: 28rpx;
  font-weight: 600;
  color: #ffffff;
  text-align: center;
}

.manual-btn.disabled {
  opacity: 0.5;
}

/* ---------- 图像 ---------- */
.camera-container {
  margin-bottom: 24rpx;
}

.camera-preview {
  height: 320rpx;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(125, 116, 107, 0.08);
  border: 4rpx dashed var(--border);
  border-radius: 24rpx;
}

.camera-preview.captured {
  border-style: solid;
  border-color: var(--primary);
  background: rgba(143, 166, 142, 0.12);
}

.camera-placeholder,
.captured-frame {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 14rpx;
}

.camera-placeholder-emoji,
.captured-emoji {
  font-size: 72rpx;
}

.camera-placeholder-text,
.captured-text {
  font-size: 26rpx;
  color: var(--text-2);
}

.camera-actions {
  display: flex;
  gap: 20rpx;
  margin-top: 28rpx;
}

.action-btn {
  flex: 1;
  padding: 26rpx 0;
  background: rgba(125, 116, 107, 0.1);
  border-radius: 24rpx;
  font-size: 28rpx;
  color: var(--text-1);
  text-align: center;
}

.action-btn.primary {
  background: linear-gradient(135deg, var(--primary), #9db89c);
  color: #ffffff;
  font-weight: 600;
}

.action-btn.disabled {
  opacity: 0.5;
}

/* ---------- 文本 ---------- */
.text-area-wrapper {
  position: relative;
  margin-bottom: 28rpx;
}

.text-area {
  width: 100%;
  height: 240rpx;
  padding: 24rpx 28rpx;
  background: rgba(255, 255, 255, 0.9);
  border: 2rpx solid var(--border);
  border-radius: 24rpx;
  font-size: 28rpx;
  color: var(--text-1);
  box-sizing: border-box;
}

.char-count {
  position: absolute;
  right: 24rpx;
  bottom: 16rpx;
  font-size: 22rpx;
  color: var(--text-3);
}

.submit-btn {
  padding: 28rpx 0;
  background: linear-gradient(135deg, var(--primary), #9db89c);
  border-radius: 24rpx;
  font-size: 30rpx;
  font-weight: 600;
  color: #ffffff;
  text-align: center;
}

.submit-btn.disabled {
  opacity: 0.5;
}

/* ---------- 跌倒检测 ---------- */
.card-header-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 24rpx;
}

.section-title {
  font-size: 34rpx;
  font-weight: 700;
  color: var(--text-1);
}

.link-more {
  font-size: 26rpx;
  color: var(--primary);
}

.mini-switch {
  width: 80rpx;
  height: 44rpx;
  padding: 4rpx;
  display: flex;
  align-items: center;
  background: rgba(125, 116, 107, 0.2);
  border-radius: 22rpx;
}

.mini-switch.on {
  background: var(--primary);
}

.mini-switch-knob {
  width: 36rpx;
  height: 36rpx;
  background: #ffffff;
  border-radius: 50%;
  transition: transform 0.2s ease;
}

.mini-switch.on .mini-switch-knob {
  transform: translateX(36rpx);
}

.fall-status-row {
  display: flex;
  align-items: center;
  gap: 20rpx;
}

.fall-status-icon {
  font-size: 48rpx;
}

.fall-status-text {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 6rpx;
}

.fall-status-title {
  font-size: 30rpx;
  font-weight: 600;
  color: var(--text-1);
}

.fall-status-desc {
  font-size: 24rpx;
  color: var(--text-2);
}

.fall-badge {
  padding: 8rpx 20rpx;
  font-size: 24rpx;
  border-radius: 999rpx;
}

.badge-normal {
  background: var(--primary-l);
  color: var(--primary-d);
}

.badge-warning {
  background: var(--warning-l);
  color: var(--warning);
}

.badge-alert {
  background: var(--danger-l);
  color: var(--danger);
}

/* ---------- 结果列表 ---------- */
.result-list {
  display: flex;
  flex-direction: column;
  gap: 20rpx;
}

.result-item {
  display: flex;
  flex-direction: column;
  gap: 12rpx;
  padding: 24rpx;
  background: rgba(125, 116, 107, 0.05);
  border-radius: 24rpx;
}

.result-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.result-type {
  padding: 4rpx 18rpx;
  font-size: 22rpx;
  border-radius: 999rpx;
  background: var(--primary-l);
  color: var(--primary-d);
}

.result-type.type-image {
  background: rgba(212, 165, 116, 0.15);
  color: var(--warning);
}

.result-type.type-text {
  background: rgba(125, 116, 107, 0.12);
  color: var(--text-2);
}

.result-time {
  font-size: 22rpx;
  color: var(--text-3);
}

.result-content {
  font-size: 28rpx;
  color: var(--text-1);
  line-height: 1.6;
}

.result-analysis {
  font-size: 26rpx;
  color: var(--text-2);
  line-height: 1.6;
}

.result-alert {
  font-size: 24rpx;
  color: var(--warning);
}

/* ---------- 大字模式增强 ---------- */
.elder-mode .elder-mode-bar {
  padding: 32rpx;
}

.elder-mode .mode-tab-label,
.elder-mode .elder-mode-desc,
.elder-mode .card-desc,
.elder-mode .recording-idle,
.elder-mode .manual-label {
  font-size: 30rpx;
}

.elder-mode .record-btn {
  width: 300rpx;
  height: 300rpx;
}

.elder-mode .manual-btn,
.elder-mode .submit-btn,
.elder-mode .action-btn {
  padding: 40rpx 0;
  font-size: 38rpx;
}

.ai-chat-page {
  height: 100vh;
  display: flex;
  flex-direction: column;
  background: linear-gradient(180deg, #f4efe6 0%, #eef3ee 100%);
  box-sizing: border-box;
}

/* ---------- 顶部固定栏 ---------- */
.header-bar {
  flex-shrink: 0;
  padding: 24rpx 32rpx;
  background: linear-gradient(135deg, #8fa68e 0%, #7bc9a6 100%);
  box-shadow: 0 8rpx 32rpx rgba(91, 154, 122, 0.15);
}

.header-content {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.header-left {
  display: flex;
  align-items: center;
  gap: 20rpx;
}

.header-avatar {
  width: 88rpx;
  height: 88rpx;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 48rpx;
  background: rgba(255, 255, 255, 0.25);
  border-radius: 44rpx;
}

.header-title-group {
  display: flex;
  flex-direction: column;
  gap: 4rpx;
}

.header-title {
  font-size: 38rpx;
  font-weight: 700;
  color: #ffffff;
}

.header-status {
  font-size: 24rpx;
  color: rgba(255, 255, 255, 0.85);
}

.header-right {
  display: flex;
  gap: 16rpx;
}

.header-btn {
  width: 72rpx;
  height: 72rpx;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 32rpx;
  background: rgba(255, 255, 255, 0.22);
  border-radius: 36rpx;
}

/* ---------- 消息列表 ---------- */
.messages-container {
  flex: 1;
  min-height: 0;
  padding: 28rpx 32rpx;
  box-sizing: border-box;
}

.message-wrapper {
  display: flex;
  align-items: flex-start;
  margin-bottom: 32rpx;
}

.message-wrapper.is-assistant {
  justify-content: flex-start;
}

.message-wrapper.is-user {
  justify-content: flex-end;
}

.avatar-ring {
  width: 72rpx;
  height: 72rpx;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 40rpx;
  background: linear-gradient(135deg, #8fa68e, #7bc9a6);
  border-radius: 36rpx;
  margin-right: 20rpx;
}

.avatar-ring.user-avatar {
  background: linear-gradient(135deg, #636e72, #2d3436);
  margin-right: 0;
  margin-left: 20rpx;
}

.message-bubble {
  max-width: 76%;
  padding: 24rpx 28rpx;
  border-radius: 32rpx;
}

/* AI 气泡：左白底 */
.assistant-bubble {
  background: #ffffff;
  border-left: 6rpx solid rgba(91, 154, 122, 0.4);
  border-bottom-left-radius: 10rpx;
  box-shadow: 0 8rpx 24rpx rgba(0, 0, 0, 0.06);
}

/* 用户气泡：右绿底 */
.user-bubble {
  background: linear-gradient(135deg, #8fa68e, #7bc9a6);
  border-bottom-right-radius: 10rpx;
  box-shadow: 0 8rpx 24rpx rgba(91, 154, 122, 0.2);
}

.message-content {
  font-size: 30rpx;
  line-height: 1.7;
  color: #2d3436;
  white-space: pre-wrap;
  word-break: break-word;
}

.user-bubble .message-content {
  color: #ffffff;
}

.message-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24rpx;
  margin-top: 14rpx;
}

.message-time {
  font-size: 22rpx;
  color: #9ca3af;
}

.user-bubble .message-time {
  color: rgba(255, 255, 255, 0.8);
}

.message-actions {
  display: flex;
  gap: 14rpx;
}

.meta-btn {
  width: 56rpx;
  height: 56rpx;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 28rpx;
  background: rgba(91, 154, 122, 0.1);
  border-radius: 28rpx;
}

.meta-btn.playing {
  background: rgba(229, 90, 90, 0.15);
}

/* ---------- 思考中 ---------- */
.thinking-wrapper {
  display: flex;
  align-items: flex-start;
  margin-bottom: 32rpx;
}

.thinking-bubble {
  display: flex;
  align-items: center;
  gap: 14rpx;
}

.dot {
  width: 14rpx;
  height: 14rpx;
  background: var(--primary);
  border-radius: 50%;
  animation: dot-pulse 1.2s ease-in-out infinite;
}

.dot:nth-child(2) { animation-delay: 0.2s; }
.dot:nth-child(3) { animation-delay: 0.4s; }

@keyframes dot-pulse {
  0%, 100% { transform: scale(0.8); opacity: 0.5; }
  50% { transform: scale(1.2); opacity: 1; }
}

.thinking-text {
  font-size: 26rpx;
  color: #636e72;
}

/* ---------- 快捷提问 ---------- */
.quick-questions-container {
  margin-top: 8rpx;
  margin-bottom: 32rpx;
}

.quick-header {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12rpx;
  margin-bottom: 20rpx;
}

.quick-sparkle {
  font-size: 36rpx;
}

.quick-title {
  font-size: 26rpx;
  font-weight: 600;
  color: #636e72;
}

.quick-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 20rpx;
}

.quick-item {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 20rpx;
  padding: 24rpx 28rpx;
  background: #ffffff;
  border: 2rpx solid rgba(91, 154, 122, 0.15);
  border-radius: 28rpx;
  box-shadow: 0 6rpx 20rpx rgba(0, 0, 0, 0.05);
}

.quick-item:active {
  transform: scale(0.98);
  opacity: 0.9;
}

.quick-icon-wrapper {
  width: 64rpx;
  height: 64rpx;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 34rpx;
  background: linear-gradient(135deg, rgba(143, 166, 142, 0.2), rgba(123, 201, 166, 0.15));
  border-radius: 32rpx;
}

.quick-question-text {
  flex: 1;
  font-size: 28rpx;
  font-weight: 500;
  color: #2d3436;
}

.bottom-anchor {
  height: 24rpx;
}

/* ---------- 底部输入栏 ---------- */
.action-bar {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  gap: 20rpx;
  padding: 20rpx 32rpx;
  padding-bottom: calc(20rpx + env(safe-area-inset-bottom));
  background: var(--surface);
  box-shadow: 0 -4rpx 20rpx rgba(0, 0, 0, 0.06);
}

.input-box {
  flex: 1;
  padding: 24rpx 32rpx;
  background: rgba(125, 116, 107, 0.08);
  border-radius: 40rpx;
  font-size: 30rpx;
  color: var(--text-1);
}

.field-ph {
  color: var(--text-3);
}

.send-btn {
  width: 88rpx;
  height: 88rpx;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 40rpx;
  color: #ffffff;
  background: linear-gradient(135deg, var(--primary), #9db89c);
  border-radius: 44rpx;
  box-shadow: 0 8rpx 20rpx rgba(143, 166, 142, 0.3);
}

.send-btn.disabled {
  opacity: 0.45;
  box-shadow: none;
}

/* ---------- 清空确认 ---------- */
.modal-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 100;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 64rpx;
  background: rgba(0, 0, 0, 0.45);
}

.confirm-box {
  width: 100%;
  padding: 48rpx 40rpx;
  background: var(--surface);
  border-radius: 32rpx;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.confirm-title {
  font-size: 36rpx;
  font-weight: 700;
  color: var(--text-1);
}

.confirm-message {
  margin-top: 20rpx;
  font-size: 28rpx;
  color: var(--text-2);
  text-align: center;
}

.confirm-actions {
  display: flex;
  gap: 20rpx;
  width: 100%;
  margin-top: 40rpx;
}

.modal-btn {
  flex: 1;
  padding: 24rpx 0;
  border-radius: 24rpx;
  font-size: 30rpx;
  font-weight: 600;
  text-align: center;
}

.modal-btn.cancel {
  background: rgba(125, 116, 107, 0.1);
  color: var(--text-2);
}

.modal-btn.send {
  background: var(--primary);
  color: #ffffff;
}

.profile-page {
  min-height: 100vh;
  background: linear-gradient(180deg, #f4efe6 0%, #f5f0e6 100%);
}

/* ---------- ① 用户卡 ---------- */
.user-section {
  padding: 32rpx;
}

.user-card {
  padding: 36rpx;
  background: linear-gradient(135deg, #8fa68e 0%, #a8c4a7 100%);
  border-radius: var(--radius-lg);
  box-shadow: 0 12rpx 40rpx rgba(143, 166, 142, 0.25);
}

.user-header {
  display: flex;
  align-items: center;
  gap: 24rpx;
}

.user-avatar {
  width: 120rpx;
  height: 120rpx;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 52rpx;
  font-weight: 700;
  color: var(--primary-d);
  background: rgba(255, 255, 255, 0.9);
  border-radius: 50%;
  box-shadow: 0 8rpx 24rpx rgba(0, 0, 0, 0.08);
}

.user-main {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 12rpx;
}

.user-name {
  font-size: 40rpx;
  font-weight: 700;
  color: #ffffff;
}

.user-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 12rpx;
}

.user-badge {
  padding: 6rpx 20rpx;
  font-size: 22rpx;
  color: #ffffff;
  background: rgba(255, 255, 255, 0.25);
  border-radius: 999rpx;
}

.user-badge.light {
  background: rgba(255, 255, 255, 0.18);
}

.user-settings-btn {
  width: 72rpx;
  height: 72rpx;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 36rpx;
  background: rgba(255, 255, 255, 0.25);
  border-radius: 36rpx;
}

/* 统计三宫格 */
.stats-grid {
  display: flex;
  align-items: center;
  margin-top: 36rpx;
  padding-top: 28rpx;
  border-top: 2rpx solid rgba(255, 255, 255, 0.25);
}

.stat-item {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6rpx;
}

.stat-value {
  font-size: 44rpx;
  font-weight: 700;
  color: #ffffff;
}

.stat-value.primary {
  color: #fff3d6;
}

.stat-label {
  font-size: 24rpx;
  color: rgba(255, 255, 255, 0.85);
}

.stat-divider {
  width: 2rpx;
  height: 56rpx;
  background: rgba(255, 255, 255, 0.25);
}

/* ---------- ② 功能入口 ---------- */
.menu-section {
  padding: 0 32rpx;
}

.menu-card {
  background: var(--surface);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow);
  padding: 0 32rpx;
}

.menu-item {
  display: flex;
  align-items: center;
  gap: 24rpx;
  padding: 30rpx 0;
  border-bottom: 2rpx solid var(--divider);
}

.menu-item:last-child {
  border-bottom: none;
}

.menu-item:active {
  opacity: 0.7;
}

.menu-icon-wrapper {
  width: 76rpx;
  height: 76rpx;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 36rpx;
  border-radius: 24rpx;
}

.menu-text {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 4rpx;
}

.menu-title {
  font-size: 32rpx;
  font-weight: 500;
  color: var(--text-1);
}

.menu-value {
  font-size: 24rpx;
  color: var(--text-2);
}

.menu-arrow {
  font-size: 40rpx;
  color: var(--text-3);
  line-height: 1;
}

.menu-badge {
  padding: 6rpx 18rpx;
  font-size: 22rpx;
  color: var(--primary-d);
  background: var(--primary-l);
  border-radius: 999rpx;
}

/* 开关 */
.menu-switch {
  width: 88rpx;
  height: 48rpx;
  padding: 4rpx;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  background: rgba(125, 116, 107, 0.2);
  border-radius: 24rpx;
  transition: background 0.2s ease;
}

.menu-switch.on {
  background: var(--primary);
}

.menu-switch-knob {
  width: 40rpx;
  height: 40rpx;
  background: #ffffff;
  border-radius: 50%;
  transition: transform 0.2s ease;
}

.menu-switch.on .menu-switch-knob {
  transform: translateX(40rpx);
}

/* ---------- ③ 版本号 ---------- */
.version-text {
  display: block;
  margin-top: 48rpx;
  text-align: center;
  font-size: 24rpx;
  color: var(--text-3);
}

/* ---------- 账号操作面板 ---------- */
.modal-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 100;
  display: flex;
  align-items: flex-end;
  background: rgba(0, 0, 0, 0.45);
}

.action-sheet {
  width: 100%;
  padding: 24rpx 24rpx calc(24rpx + env(safe-area-inset-bottom));
  background: var(--surface);
  border-radius: 32rpx 32rpx 0 0;
}

.sheet-item {
  padding: 32rpx 0;
  text-align: center;
  font-size: 32rpx;
  color: var(--text-1);
  border-bottom: 2rpx solid var(--divider);
}

.sheet-item.danger {
  color: var(--danger);
}

.sheet-item.cancel {
  margin-top: 16rpx;
  border-bottom: none;
  color: var(--text-2);
}

/* ---------- 大字模式增强 ---------- */
.elder-mode .menu-title {
  font-size: 44rpx;
}

.elder-mode .menu-value {
  font-size: 32rpx;
}

.elder-mode .user-name {
  font-size: 52rpx;
}

.elder-mode .stat-value {
  font-size: 56rpx;
}

.page-inner {
  padding: 24rpx;
}

/* ---------- 品牌 ---------- */
.brand {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 60rpx 0 48rpx;
}

.logo {
  width: 176rpx;
  height: 176rpx;
  border-radius: 48rpx;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg, var(--primary), #a8c4a7);
  box-shadow: 0 12rpx 32rpx rgba(143, 166, 142, 0.28);
}

.logo-icon {
  font-size: 88rpx;
}

.app-name {
  margin-top: 28rpx;
  font-size: 42rpx;
  font-weight: 700;
  color: var(--text-1);
  letter-spacing: 2rpx;
}

.app-slogan {
  margin-top: 10rpx;
  font-size: 26rpx;
  color: var(--text-2);
}

.version-chip {
  margin-top: 20rpx;
  padding: 8rpx 28rpx;
  border-radius: var(--radius-full);
  background: var(--primary-l);
  color: var(--primary-d);
  font-size: 24rpx;
}

/* ---------- 介绍 ---------- */
.intro {
  display: block;
  font-size: 26rpx;
  color: var(--text-2);
  line-height: 1.9;
}

.feature-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 20rpx;
  margin-top: 28rpx;
}

.feature-item {
  width: calc(50% - 10rpx);
  box-sizing: border-box;
  padding: 24rpx;
  border-radius: var(--radius-sm);
  background: var(--surface-2);
  display: flex;
  flex-direction: column;
}

.feature-icon {
  font-size: 40rpx;
}

.feature-title {
  margin-top: 10rpx;
  font-size: 28rpx;
  font-weight: 600;
  color: var(--text-1);
}

.feature-desc {
  margin-top: 4rpx;
  font-size: 22rpx;
  color: var(--text-2);
}

/* ---------- 列表 ---------- */
.item-text {
  display: flex;
  flex-direction: column;
}

.item-title {
  font-size: 30rpx;
  color: var(--text-1);
}

.item-desc {
  margin-top: 4rpx;
  font-size: 22rpx;
  color: var(--text-3);
}

/* ---------- 备案 ---------- */
.record-row {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24rpx;
  padding: 20rpx 0;
  border-bottom: 2rpx solid var(--divider);
}

.record-row:last-of-type {
  border-bottom: none;
}

.record-label {
  font-size: 26rpx;
  color: var(--text-2);
  flex-shrink: 0;
}

.record-value {
  flex: 1;
  font-size: 26rpx;
  color: var(--text-1);
  text-align: right;
}

.record-tip {
  display: block;
  margin-top: 16rpx;
  font-size: 22rpx;
  color: var(--text-3);
  line-height: 1.7;
}

/* ---------- 页脚 ---------- */
.footer {
  padding: 40rpx 0 64rpx;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.footer-line {
  font-size: 22rpx;
  color: var(--text-3);
  line-height: 1.8;
}

