dsl.css:
.sleep-page {
  min-height: 100vh;
  padding: 32rpx;
  background: linear-gradient(180deg, #f4efe6 0%, #eef1ee 100%);
}

/* ---------- ① Hero ---------- */
.hero-card {
  position: relative;
  padding: 40rpx 32rpx;
  margin-bottom: 32rpx;
  background: linear-gradient(135deg, #5b7a94 0%, #7d9bb0 100%);
  border-radius: var(--radius-lg);
  box-shadow: 0 12rpx 40rpx rgba(91, 122, 148, 0.25);
  overflow: hidden;
}

.hero-deco {
  position: absolute;
  top: 8rpx;
  right: 24rpx;
  font-size: 140rpx;
  opacity: 0.15;
}

.hero-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 32rpx;
}

.hero-title {
  font-size: 38rpx;
  font-weight: 700;
  color: #ffffff;
}

.hero-level {
  padding: 6rpx 24rpx;
  font-size: 24rpx;
  border-radius: 999rpx;
  background: rgba(255, 255, 255, 0.25);
  color: #ffffff;
}

.hero-body {
  display: flex;
  align-items: center;
  gap: 32rpx;
}

.score-ring {
  width: 220rpx;
  height: 220rpx;
  flex-shrink: 0;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
}

.ring-inner {
  width: 168rpx;
  height: 168rpx;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  background: rgba(255, 255, 255, 0.95);
  border-radius: 50%;
}

.score-num {
  font-size: 64rpx;
  font-weight: 700;
  color: var(--primary-d);
  line-height: 1.1;
}

.score-unit {
  font-size: 22rpx;
  color: var(--text-2);
}

.hero-detail {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 18rpx;
}

.detail-row {
  display: flex;
  flex-direction: column;
  gap: 4rpx;
}

.detail-label {
  font-size: 24rpx;
  color: rgba(255, 255, 255, 0.8);
}

.detail-value {
  font-size: 32rpx;
  font-weight: 600;
  color: #ffffff;
}

/* ---------- ② 输入 ---------- */
.card-title {
  display: block;
  margin-bottom: 24rpx;
  font-size: 34rpx;
  font-weight: 600;
  color: var(--text-1);
}

.slider-box {
  padding: 24rpx 0;
}

.slider-value-row {
  display: flex;
  align-items: baseline;
  justify-content: center;
  gap: 12rpx;
  margin-bottom: 16rpx;
}

.slider-value {
  font-size: 72rpx;
  font-weight: 700;
  color: var(--primary-d);
  line-height: 1.1;
}

.slider-unit {
  font-size: 28rpx;
  color: var(--text-2);
}

.slider {
  width: 100%;
  margin: 16rpx 0;
}

.slider-labels {
  display: flex;
  justify-content: space-between;
  font-size: 22rpx;
  color: var(--text-3);
}

.time-row {
  display: flex;
  gap: 24rpx;
  margin-top: 24rpx;
}

.time-field {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 12rpx;
}

.time-label {
  font-size: 26rpx;
  color: var(--text-2);
}

.time-picker {
  padding: 24rpx;
  background: rgba(125, 116, 107, 0.06);
  border-radius: 20rpx;
  font-size: 30rpx;
  color: var(--text-1);
  text-align: center;
}

.analyze-btn {
  margin-top: 32rpx;
  padding: 30rpx 0;
  background: linear-gradient(135deg, var(--primary), #9db89c);
  border-radius: 24rpx;
  font-size: 32rpx;
  font-weight: 600;
  color: #ffffff;
  text-align: center;
}

.analyze-btn.disabled {
  opacity: 0.5;
}

/* ---------- ③ 睡眠结构 ---------- */
.structure-list {
  display: flex;
  flex-direction: column;
  gap: 28rpx;
}

.structure-item {
  display: flex;
  flex-direction: column;
  gap: 10rpx;
}

.structure-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.structure-name-row {
  display: flex;
  align-items: center;
  gap: 14rpx;
}

.structure-dot {
  width: 20rpx;
  height: 20rpx;
  border-radius: 50%;
}

.structure-name {
  font-size: 30rpx;
  color: var(--text-1);
}

.structure-percent {
  font-size: 30rpx;
  font-weight: 700;
  color: var(--primary-d);
}

.structure-track {
  width: 100%;
  height: 16rpx;
  background: rgba(125, 116, 107, 0.12);
  border-radius: 8rpx;
  overflow: hidden;
}

.structure-fill {
  height: 100%;
  border-radius: 8rpx;
  transition: width 0.4s ease;
}

.structure-desc {
  font-size: 24rpx;
  color: var(--text-2);
}

/* ---------- ④ 趋势 ---------- */
.trend-chart {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  height: 320rpx;
  padding-top: 24rpx;
}

.trend-col {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10rpx;
  height: 100%;
}

.trend-hours {
  font-size: 20rpx;
  color: var(--text-2);
}

.trend-bar-wrapper {
  flex: 1;
  width: 100%;
  display: flex;
  align-items: flex-end;
  justify-content: center;
}

.trend-bar {
  width: 40rpx;
