.forgot-page {
  min-height: 100vh;
  padding: 80rpx 64rpx 64rpx;
  background: linear-gradient(180deg, #f4efe6 0%, #faf7f1 100%);
}

.fp-header {
  display: flex;
  flex-direction: column;
  margin-bottom: 48rpx;
}

.fp-title {
  font-size: 52rpx;
  font-weight: 700;
  color: #2f3a2f;
}

.fp-sub {
  margin-top: 12rpx;
  font-size: 28rpx;
  color: var(--text-2);
}

/* ---------- 步骤条 ---------- */
.step-row {
  display: flex;
  align-items: flex-start;
  margin-bottom: 56rpx;
}

.step-item {
  position: relative;
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10rpx;
}

.step-dot {
  width: 56rpx;
  height: 56rpx;
  border-radius: 28rpx;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 26rpx;
  font-weight: 600;
  color: var(--text-3);
  background: rgba(125, 116, 107, 0.1);
}

.step-dot.active {
  background: var(--primary);
  color: #ffffff;
}

.step-dot.done {
  background: var(--primary-d);
  color: #ffffff;
}

.step-label {
  font-size: 24rpx;
  color: var(--text-3);
}

.step-label.active {
  color: var(--primary-d);
  font-weight: 600;
}

.step-line {
  position: absolute;
  top: 28rpx;
  left: 50%;
  width: 100%;
  height: 2rpx;
  background: rgba(125, 116, 107, 0.15);
  z-index: -1;
}

.step-line.active {
  background: var(--primary);
}

/* ---------- 表单 ---------- */
.form-area {
  display: flex;
  flex-direction: column;
}

.field-group {
  margin-bottom: 36rpx;
}

.field-label {
  display: block;
  margin-bottom: 18rpx;
  padding-left: 8rpx;
  font-size: 30rpx;
  font-weight: 500;
  color: #2f3a2f;
}

.input-box {
  display: flex;
  align-items: center;
  gap: 20rpx;
  padding: 26rpx 36rpx;
  background: rgba(255, 255, 255, 0.9);
  border: 2rpx solid rgba(143, 166, 142, 0.15);
  border-radius: 36rpx;
  box-shadow: 0 4rpx 16rpx rgba(0, 0, 0, 0.04);
}

.input-icon {
  font-size: 36rpx;
  line-height: 1;
}

.field-input {
  flex: 1;
  min-width: 0;
  font-size: 32rpx;
  color: #2f3a2f;
}

.field-ph {
  color: var(--text-3);
}

.code-wrapper {
  display: flex;
  gap: 20rpx;
  align-items: center;
}

.flex-1 {
  flex: 1;
}

.code-btn {
  min-width: 200rpx;
  padding: 28rpx 32rpx;
  background: rgba(143, 166, 142, 0.12);
  border: 2rpx solid rgba(143, 166, 142, 0.2);
  border-radius: 36rpx;
  font-size: 28rpx;
  color: var(--primary-d);
  text-align: center;
  white-space: nowrap;
}

.code-btn.disabled {
  background: rgba(125, 116, 107, 0.08);
  border-color: transparent;
  color: var(--text-3);
}

.password-toggle {
  font-size: 34rpx;
  padding: 8rpx;
}

/* ---------- 强度 ---------- */
.strength-row {
  display: flex;
  align-items: center;
  gap: 16rpx;
  margin-bottom: 40rpx;
}

.strength-label {
  font-size: 26rpx;
  color: var(--text-2);
}

.strength-bars {
  flex: 1;
  display: flex;
  gap: 10rpx;
}

.strength-bar {
  flex: 1;
