.history-item {
  display: flex; align-items: center; gap: 20rpx;
  padding: 24rpx 0; border-bottom: 2rpx solid var(--divider);
}
.history-item:last-child { border-bottom: none; }
.history-dot {
  width: 16rpx; height: 16rpx; border-radius: 50%;
  background: var(--primary); flex-shrink: 0;
}
.history-info { flex: 1; display: flex; flex-direction: column; gap: 6rpx; }
.history-addr { font-size: 28rpx; color: var(--text-1); }
.history-time { font-size: 22rpx; color: var(--text-3); }
.history-tag { font-size: 22rpx; padding: 4rpx 16rpx; border-radius: var(--radius-full); }
.history-tag.in { background: var(--primary-l); color: var(--primary-d); }
.history-tag.out { background: var(--warning-l); color: var(--warning); }

.login-page {
  min-height: 100vh;
  padding: 96rpx 64rpx 64rpx;
  background: linear-gradient(180deg, #f4efe6 0%, #faf7f1 100%);
  display: flex;
  flex-direction: column;
}

/* ---------- ① 品牌区 ---------- */
.brand-area {
  display: flex;
  flex-direction: column;
  align-items: center;
  margin-bottom: 72rpx;
}

.brand-logo {
  width: 200rpx;
  height: 200rpx;
  border-radius: 80rpx;
  background: linear-gradient(135deg, #8fa68e, #a8c4a7);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 80rpx;
  box-shadow: 0 16rpx 48rpx rgba(143, 166, 142, 0.25);
  animation: logo-float 3s ease-in-out infinite;
}

@keyframes logo-float {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-12rpx); }
}

.brand-name {
  margin-top: 40rpx;
  font-size: 52rpx;
  font-weight: 600;
  color: #2f3a2f;
  letter-spacing: 4rpx;
}

.brand-slogan {
  margin-top: 12rpx;
  font-size: 30rpx;
  color: var(--text-2);
  letter-spacing: 2rpx;
}

/* ---------- ② 登录方式 Tab ---------- */
.login-tabs {
  display: flex;
  gap: 16rpx;
  padding: 12rpx;
  margin-bottom: 56rpx;
  background: rgba(255, 255, 255, 0.6);
  border-radius: 56rpx;
  box-shadow: 0 4rpx 16rpx rgba(0, 0, 0, 0.04);
}

.tab-item {
  flex: 1;
  padding: 26rpx 0;
  border-radius: 44rpx;
  text-align: center;
  font-size: 28rpx;
  color: var(--text-2);
  transition: all 0.25s ease;
}

.tab-item.active {
  background: var(--primary);
  color: #ffffff;
  font-weight: 600;
  box-shadow: 0 8rpx 24rpx rgba(143, 166, 142, 0.25);
}

/* ---------- ③ 表单区 ---------- */
.form-area,
.wechat-area {
  flex: 1;
}

.field-group {
  margin-bottom: 40rpx;
}

.field-label {
  display: block;
  margin-bottom: 18rpx;
  padding-left: 8rpx;
  font-size: 30rpx;
  font-weight: 500;
  color: #2f3a2f;
}

.input-box {
  display: flex;
  align-items: center;
  gap: 20rpx;
  padding: 26rpx 36rpx;
  background: rgba(255, 255, 255, 0.9);
  border: 2rpx solid rgba(143, 166, 142, 0.15);
  border-radius: 36rpx;
  box-shadow: 0 4rpx 16rpx rgba(0, 0, 0, 0.04);
}

.input-icon {
  font-size: 36rpx;
  line-height: 1;
}

.field-input {
  flex: 1;
  min-width: 0;
  font-size: 32rpx;
  color: #2f3a2f;
}

.field-ph {
  color: var(--text-3);
}

.code-wrapper {
  display: flex;
  gap: 20rpx;
  align-items: center;
}

.flex-1 {
  flex: 1;
}

.code-btn {
  min-width: 220rpx;
  padding: 28rpx 32rpx;
  background: rgba(143, 166, 142, 0.12);
  border: 2rpx solid rgba(143, 166, 142, 0.2);
  border-radius: 36rpx;
  font-size: 28rpx;
  color: var(--primary-d);
  font-weight: 500;
  text-align: center;
  white-space: nowrap;
}

.code-btn.disabled {
  background: rgba(125, 116, 107, 0.08);
  border-color: transparent;
  color: var(--text-3);
}

.login-btn {
  width: 100%;
  margin-top: 40rpx;
  padding: 34rpx 0;
  background: linear-gradient(135deg, #8fa68e, #9db89c);
  border-radius: 36rpx;
  font-size: 34rpx;
  font-weight: 600;
  color: #ffffff;
  letter-spacing: 4rpx;
  text-align: center;
  box-shadow: 0 12rpx 40rpx rgba(143, 166, 142, 0.25);
}

.login-btn:active {
  opacity: 0.9;
  transform: scale(0.98);
}

/* 未勾选协议时置灰，但点击仍有提示（由函数内部拦截） */
.disabled-btn {
  opacity: 0.5;
  box-shadow: none;
}

.password-toggle {
  font-size: 34rpx;
  padding: 8rpx;
}

.forgot-row {
  display: flex;
  justify-content: flex-end;
  padding: 8rpx 0;
}

.link-blue {
  font-size: 28rpx;
  font-weight: 500;
  color: var(--primary-d);
}

/* ---------- 微信登录 ---------- */
.wechat-area {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding-top: 32rpx;
}

.wechat-tip {
  font-size: 30rpx;
  line-height: 1.6;
  color: var(--text-2);
  text-align: center;
}

.wechat-tip.sub {
  margin-bottom: 48rpx;
}

.wechat-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 20rpx;
  width: 100%;
  padding: 34rpx 0;
  background: #07c160;
  border-radius: 36rpx;
  font-size: 34rpx;
  font-weight: 600;
  color: #ffffff;
  letter-spacing: 4rpx;
  box-shadow: 0 12rpx 40rpx rgba(7, 193, 96, 0.25);
}

.wechat-icon {
  font-size: 44rpx;
}

/* ---------- ④ 协议区 ---------- */
.agreement-check-area {
  margin-top: 64rpx;
  padding: 28rpx;
  background: rgba(255, 255, 255, 0.6);
  border-radius: 28rpx;
  display: flex;
  flex-direction: column;
  gap: 16rpx;
}

.check-row {
  display: flex;
  align-items: center;
  gap: 16rpx;
}

.checkbox {
  width: 40rpx;
  height: 40rpx;
  flex-shrink: 0;
  border: 3rpx solid var(--primary);
  border-radius: 20rpx;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 24rpx;
  color: #ffffff;
}

.checkbox.checked {
  background: var(--primary);
}

.check-text {
  font-size: 26rpx;
  font-weight: 500;
  color: #2f3a2f;
}

.agreement-links-row {
  padding-left: 56rpx;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
}

.agreement-links-row .link-blue {
  font-size: 26rpx;
}

.separator {
  font-size: 26rpx;
  color: var(--text-2);
}

/* ---------- ⑤ 去注册 ---------- */
.register-row {
  margin-top: 40rpx;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8rpx;
}

.register-text {
  font-size: 28rpx;
  color: var(--text-2);
}

.page { padding: 24rpx calc(24rpx) calc(120rpx + env(safe-area-inset-bottom)); }

.adherence-card { display: flex; flex-direction: column; align-items: center; }

.ring-wrap { margin: 16rpx 0 24rpx; }
.ring {
  width: 320rpx; height: 320rpx; border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  box-shadow: var(--shadow-lg);
}
.ring-inner {
  width: 250rpx; height: 250rpx; border-radius: 50%;
  background: var(--surface);
  display: flex; flex-direction: column; align-items: center; justify-content: center;
}
.ring-value { font-size: 80rpx; font-weight: 800; color: var(--primary-d); line-height: 1.1; }
.ring-unit { font-size: 26rpx; color: var(--text-2); margin-top: -8rpx; }
.ring-label { font-size: 22rpx; color: var(--text-3); margin-top: 8rpx; }

.ring-advice {
  font-size: 26rpx; color: var(--text-2); text-align: center;
  line-height: 1.6; padding: 0 24rpx; margin-bottom: 12rpx;
}

.stat-row {
  display: flex; align-items: center; width: 100%;
  padding-top: 24rpx; border-top: 2rpx solid var(--divider);
}
.stat-cell { flex: 1; display: flex; flex-direction: column; align-items: center; gap: 8rpx; }
.stat-value { font-size: 44rpx; font-weight: 700; }
.stat-value.ok { color: var(--primary-d); }
.stat-value.danger { color: var(--danger); }
.stat-value.warn { color: var(--warning); }
.stat-label { font-size: 22rpx; color: var(--text-2); }
.stat-divider { width: 2rpx; height: 56rpx; background: var(--divider); }

.section-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 8rpx; }
.header-sub { font-size: 24rpx; color: var(--text-3); }

.loading-box { padding: 64rpx 0; text-align: center; }
.loading-text { font-size: 28rpx; color: var(--text-2); }

.group { margin-bottom: 24rpx; }
.group-header {
  display: flex; align-items: center; justify-content: space-between;
  padding: 12rpx 0; border-bottom: 2rpx solid var(--divider);
}
.group-date { font-size: 26rpx; font-weight: 600; color: var(--primary-d); }
.group-count { font-size: 22rpx; color: var(--text-3); }

.record-item { display: flex; align-items: center; gap: 20rpx; padding: 22rpx 0; }
.record-icon {
  width: 72rpx; height: 72rpx; border-radius: var(--radius-sm); flex-shrink: 0;
  display: flex; align-items: center; justify-content: center; font-size: 32rpx;
  background: var(--surface-2);
}
.st-taken { background: var(--primary-l); }
.st-missed { background: var(--danger-l); }
.st-skipped { background: var(--warning-l); }

.record-info { flex: 1; display: flex; flex-direction: column; gap: 8rpx; }
.record-line { display: flex; align-items: center; gap: 12rpx; }
.record-name { font-size: 30rpx; font-weight: 600; color: var(--text-1); }
.status-tag { font-size: 20rpx; padding: 2rpx 14rpx; border-radius: var(--radius-full); }
.status-tag.st-taken { color: var(--primary-d); }
.status-tag.st-missed { color: var(--danger); }
.status-tag.st-skipped { color: var(--warning); }
.record-meta { font-size: 24rpx; color: var(--text-2); }
.record-taken { font-size: 22rpx; color: var(--text-3); }

