dsl.css:
.medicine-page {
  min-height: 100vh;
  padding: 32rpx 32rpx 160rpx;
  background: linear-gradient(180deg, #f4efe6 0%, #f5f0e6 100%);
}

/* ---------- ① 进度三宫格 ---------- */
.progress-card {
  padding: 36rpx 32rpx;
  margin-bottom: 32rpx;
  background: linear-gradient(135deg, #8fa68e 0%, #a8c4a7 100%);
  border-radius: var(--radius-lg);
  box-shadow: 0 12rpx 40rpx rgba(143, 166, 142, 0.25);
}

.progress-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 28rpx;
}

.progress-title {
  font-size: 34rpx;
  font-weight: 700;
  color: #ffffff;
}

.progress-rate {
  padding: 6rpx 20rpx;
  font-size: 24rpx;
  color: #ffffff;
  background: rgba(255, 255, 255, 0.25);
  border-radius: 999rpx;
}

.progress-grid {
  display: flex;
  align-items: center;
}

.progress-cell {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6rpx;
}

.progress-value {
  font-size: 56rpx;
  font-weight: 700;
  color: #ffffff;
  line-height: 1.1;
}

.progress-value.taken {
  color: #eaffe8;
}

.progress-value.pending {
  color: #fff3d6;
}

.progress-label {
  font-size: 24rpx;
  color: rgba(255, 255, 255, 0.85);
}

.progress-divider {
  width: 2rpx;
  height: 64rpx;
  background: rgba(255, 255, 255, 0.25);
}

.progress-track {
  width: 100%;
  height: 16rpx;
  margin-top: 28rpx;
  background: rgba(255, 255, 255, 0.25);
  border-radius: 8rpx;
  overflow: hidden;
}

.progress-fill {
  height: 100%;
  background: #ffffff;
  border-radius: 8rpx;
  transition: width 0.4s ease;
}

.progress-hint {
  display: block;
  margin-top: 16rpx;
  font-size: 24rpx;
  color: rgba(255, 255, 255, 0.9);
}

/* ---------- ② Tab ---------- */
.tab-row {
  display: flex;
  gap: 16rpx;
  margin-bottom: 32rpx;
}

.tab-item {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12rpx;
  padding: 26rpx 0;
  background: var(--surface);
  border: 4rpx solid transparent;
  border-radius: var(--radius);
  font-size: 30rpx;
  color: var(--text-2);
  box-shadow: var(--shadow);
}

.tab-item.active {
  background: rgba(143, 166, 142, 0.16);
  border-color: var(--primary);
  color: var(--primary-d);
  font-weight: 600;
}

.tab-count {
  padding: 2rpx 14rpx;
  font-size: 22rpx;
  border-radius: 999rpx;
  background: rgba(125, 116, 107, 0.12);
  color: inherit;
}

/* ---------- ③ 时段分组 ---------- */
.period-group {
  margin-bottom: 32rpx;
}

.period-header {
  display: flex;
  align-items: center;
  gap: 12rpx;
  margin-bottom: 16rpx;
  padding-left: 12rpx;
}

.period-icon {
  font-size: 32rpx;
}

.period-title {
  font-size: 30rpx;
  font-weight: 600;
  color: var(--text-1);
}

.period-count {
  font-size: 24rpx;
  color: var(--text-3);
}

.med-item {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20rpx;
  padding: 28rpx 0;
  border-bottom: 2rpx solid var(--divider);
}

.med-item.last {
  border-bottom: none;
}

.med-item.paused {
  opacity: 0.6;
}

.med-left {
  flex: 1;
  display: flex;
  gap: 20rpx;
}

.med-icon-wrapper {
  width: 72rpx;
  height: 72rpx;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 34rpx;
  background: var(--primary-l);
  border-radius: 20rpx;
}

.med-icon-wrapper.taken {
  background: var(--primary);
  color: #ffffff;
}

.med-info {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 8rpx;
}

.med-name-row {
  display: flex;
  align-items: center;
  gap: 16rpx;
}

.med-name {
  font-size: 32rpx;
  font-weight: 600;
  color: var(--text-1);
}

.med-pill {
  padding: 4rpx 16rpx;
  font-size: 20rpx;
  border-radius: 999rpx;
}

.pill-success {
  background: var(--primary-l);
  color: var(--primary-d);
}

.pill-warning {
  background: var(--warning-l);
  color: var(--warning);
}

.med-desc {
  font-size: 26rpx;
  color: var(--text-2);
}

.med-times {
  display: flex;
  flex-wrap: wrap;
  gap: 12rpx;
}

.med-time-chip {
  padding: 4rpx 16rpx;
  font-size: 22rpx;
  color: var(--primary-d);
  background: var(--primary-l);
  border-radius: 999rpx;
}

.med-notes {
  font-size: 22rpx;
  color: var(--text-3);
}

.med-right {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 12rpx;
}

.switch {
  width: 80rpx;
  height: 44rpx;
  padding: 4rpx;
  display: flex;
  align-items: center;
  background: rgba(125, 116, 107, 0.2);
  border-radius: 22rpx;
  transition: background 0.2s ease;
}

.switch.on {
  background: var(--primary);
}

.switch-knob {
  width: 36rpx;
  height: 36rpx;
  background: #ffffff;
  border-radius: 50%;
  transition: transform 0.2s ease;
}

.switch.on .switch-knob {
  transform: translateX(36rpx);
}

.med-check-btn {
  padding: 10rpx 26rpx;
  background: var(--primary);
  border-radius: 999rpx;
  font-size: 24rpx;
  color: #ffffff;
}

.med-delete-btn {
  padding: 8rpx 20rpx;
  border-radius: 999rpx;
  font-size: 22rpx;
  color: var(--danger);
  background: var(--danger-l);
}

/* ---------- ④ 依从率 ---------- */
.card-title {
  display: block;
  margin-bottom: 24rpx;
  font-size: 34rpx;
  font-weight: 600;
  color: var(--text-1);
}

.adherence-row {
  display: flex;
}

.adherence-cell {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6rpx;
}

.adherence-value {
  font-size: 40rpx;
  font-weight: 700;
  color: var(--text-1);
}

.adherence-value.good {
  color: var(--primary-d);
}

.adherence-value.warn {
  color: var(--warning);
}

.adherence-value.primary {
  color: var(--primary-d);
}

.adherence-label {
  font-size: 22rpx;
  color: var(--text-2);
}

/* ---------- 空态 ---------- */
.empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 72rpx 0;
}

.empty-icon {
  font-size: 88rpx;
  opacity: 0.4;
}

.empty-text {
  margin-top: 20rpx;
  font-size: 28rpx;
  color: var(--text-2);
}

.empty-desc {
  margin-top: 8rpx;
  font-size: 24rpx;
  color: var(--text-3);
}

/* ---------- 悬浮按钮 ---------- */
.fab {
  position: fixed;
  right: 48rpx;
  bottom: calc(72rpx + env(safe-area-inset-bottom));
  width: 112rpx;
  height: 112rpx;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 60rpx;
  color: #ffffff;
  background: linear-gradient(135deg, var(--primary), #9db89c);
  border-radius: 56rpx;
  box-shadow: 0 12rpx 32rpx rgba(143, 166, 142, 0.4);
  z-index: 50;
}

.fab:active {
  transform: scale(0.95);
}

/* ---------- 弹窗 ---------- */
.modal-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 100;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 48rpx;
  background: rgba(0, 0, 0, 0.45);
}

.modal-box {
  width: 100%;
  max-height: 80vh;
  overflow-y: auto;
  padding: 40rpx 32rpx;
  background: var(--surface);
  border-radius: 32rpx;
  display: flex;
  flex-direction: column;
  gap: 28rpx;
}

.modal-title {
  font-size: 36rpx;
  font-weight: 700;
  color: var(--text-1);
  text-align: center;
}

.form-field {
  display: flex;
  flex-direction: column;
  gap: 12rpx;
}

.form-label {
  font-size: 26rpx;
  color: var(--text-2);
}

.form-input {
  padding: 24rpx 28rpx;
  background: rgba(125, 116, 107, 0.06);
  border-radius: 20rpx;
  font-size: 30rpx;
  color: var(--text-1);
}

.field-ph {
  color: var(--text-3);
}

.freq-row,
.time-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 16rpx;
}

.freq-chip,
.time-chip {
  padding: 14rpx 28rpx;
  border-radius: 999rpx;
  font-size: 26rpx;
  color: var(--text-2);
  background: rgba(125, 116, 107, 0.08);
}

.freq-chip.active,
.time-chip.active {
  background: var(--primary);
  color: #ffffff;
}

.modal-actions {
  display: flex;
  gap: 20rpx;
  margin-top: 12rpx;
}

.modal-btn {
  flex: 1;
  padding: 26rpx 0;
  border-radius: 24rpx;
  font-size: 30rpx;
  font-weight: 600;
  text-align: center;
}

.modal-btn.cancel {
  background: rgba(125, 116, 107, 0.1);
  color: var(--text-2);
}

.modal-btn.confirm {
  background: var(--primary);
  color: #ffffff;
}

.page { padding: 32rpx 24rpx calc(120rpx + env(safe-area-inset-bottom)); }

.page-header { display: flex; align-items: center; gap: 16rpx; margin-bottom: 32rpx; }
.header-icon { font-size: 48rpx; }
.header-text { display: flex; flex-direction: column; }
.page-title { font-size: 44rpx; font-weight: 700; color: var(--text-1); }
.page-subtitle { font-size: 26rpx; color: var(--text-2); margin-top: 6rpx; }

.input-box {
  border: 2rpx solid var(--border); border-radius: var(--radius);
  background: var(--surface-2); padding: 8rpx 28rpx; margin-bottom: 20rpx;
}
.code-input {
  height: 96rpx; font-size: 40rpx; letter-spacing: 8rpx;
  color: var(--text-1); text-align: center; width: 100%;
}
.ph { color: var(--text-3); font-size: 28rpx; letter-spacing: 2rpx; }

.check-ok { display: block; font-size: 26rpx; color: var(--primary-d); margin-bottom: 20rpx; }
.check-bad { display: block; font-size: 26rpx; color: var(--danger); margin-bottom: 20rpx; }

.guide-item { display: flex; gap: 20rpx; margin-bottom: 24rpx; align-items: flex-start; }
.guide-num {
  width: 44rpx; height: 44rpx; border-radius: 50%; flex-shrink: 0;
  background: var(--primary-l); color: var(--primary-d);
  font-size: 24rpx; display: flex; align-items: center; justify-content: center;
}
.guide-text { flex: 1; font-size: 26rpx; color: var(--text-2); line-height: 1.7; }

.my-code {
  display: flex; flex-direction: column; align-items: center; gap: 12rpx;
  padding: 32rpx; border-radius: var(--radius);
  background: var(--primary-l); border: 2rpx dashed var(--primary);
}
.my-code-text { font-size: 44rpx; font-weight: 700; color: var(--primary-d); letter-spacing: 8rpx; }
.my-code-tip { font-size: 22rpx; color: var(--text-2); }
.my-code-desc { display: block; font-size: 24rpx; color: var(--text-3); text-align: center; margin-top: 20rpx; }

/* ---------- Tab ---------- */
.tabs {
  display: flex;
  gap: 12rpx;
  padding: 20rpx 24rpx;
  background: var(--bg);
  position: sticky;
  top: 0;
  z-index: 10;
}

.tab-item {
  flex: 1;
  height: 68rpx;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-full);
  background: var(--surface);
  font-size: 26rpx;
  color: var(--text-2);
}

.tab-item.active {
  background: var(--primary);
  color: #ffffff;
  font-weight: 600;
}

/* ---------- 统计 ---------- */
.summary {
  display: flex;
  padding: 0 24rpx 20rpx;
}

.summary-item {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 20rpx 0;
  background: var(--surface);
  border-radius: var(--radius);
  margin-right: 16rpx;
}

.summary-item:last-child {
  margin-right: 0;
}

.summary-value {
  font-size: 40rpx;
  font-weight: 700;
  color: var(--primary-d);
}

.summary-label {
  margin-top: 4rpx;
  font-size: 22rpx;
  color: var(--text-2);
}

/* ---------- 列表 ---------- */
.list-scroll {
  height: calc(100vh - 220rpx);
}

.list-inner {
  padding: 0 24rpx 48rpx;
}

.record-card {
  padding: 24rpx;
}

.record-head {
  display: flex;
  align-items: center;
  gap: 20rpx;
}

.record-icon {
  width: 78rpx;
  height: 78rpx;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-sm);
  background: var(--primary-l);
  font-size: 38rpx;
}

.record-main {
  flex: 1;
  min-width: 0;
}

.record-title-row {
  display: flex;
  align-items: center;
  gap: 12rpx;
}

.record-title {
  font-size: 30rpx;
  font-weight: 600;
  color: var(--text-1);
}

.record-time {
  display: block;
  margin-top: 6rpx;
  font-size: 22rpx;
  color: var(--text-3);
}

.record-value {
  display: flex;
  align-items: baseline;
  gap: 4rpx;
}

.value-num {
  font-size: 42rpx;
  font-weight: 700;
  color: var(--text-1);
}

.value-unit {
  font-size: 22rpx;
  color: var(--text-2);
}

.record-note {
  display: block;
  margin-top: 16rpx;
  padding-top: 16rpx;
  border-top: 2rpx solid var(--divider);
  font-size: 24rpx;
  color: var(--text-2);
}

.load-more {
  padding: 32rpx 0;
  text-align: center;
  font-size: 24rpx;
  color: var(--text-3);
}

.doc-scroll {
  height: 100vh;
}

.doc {
  padding: 32rpx 32rpx 96rpx;
  background: var(--bg);
}

.doc-title {
  display: block;
  font-size: 40rpx;
  font-weight: 700;
  color: var(--text-1);
  text-align: center;
  line-height: 1.5;
}

.doc-meta {
  display: block;
  margin-top: 16rpx;
  font-size: 22rpx;
  color: var(--text-3);
  text-align: center;
}

.doc-highlight {
  margin-top: 32rpx;
  padding: 24rpx;
  border-radius: var(--radius);
  background: var(--primary-l);
  border-left: 8rpx solid var(--primary);
}

.doc-highlight-text {
  font-size: 26rpx;
  color: var(--text-1);
  line-height: 1.9;
}

.doc-section {
  margin-top: 40rpx;
}

.doc-h {
  display: block;
  font-size: 32rpx;
  font-weight: 600;
  color: var(--primary-d);
  margin-bottom: 16rpx;
}

.doc-p {
  display: block;
  font-size: 27rpx;
  color: var(--text-1);
  line-height: 2;
  margin-bottom: 14rpx;
  text-align: justify;
}

.doc-foot {
  margin-top: 64rpx;
  padding-top: 32rpx;
  border-top: 2rpx solid var(--border);
  display: flex;
  flex-direction: column;
  align-items: flex-end;
}

.doc-foot-text {
  font-size: 26rpx;
  color: var(--text-2);
  line-height: 1.9;
}

.page-inner {
  padding: 24rpx;
}

/* ---------- 概览 ---------- */
.shield-card {
  text-align: center;
  background: linear-gradient(135deg, var(--surface), var(--primary-l));
}

.shield-icon {
  font-size: 88rpx;
}

.shield-title {
  display: block;
  margin-top: 12rpx;
  font-size: 34rpx;
  font-weight: 700;
  color: var(--text-1);
}

.shield-desc {
  display: block;
  margin-top: 12rpx;
  font-size: 24rpx;
  color: var(--text-2);
  line-height: 1.8;
  text-align: left;
}

/* ---------- 权限 ---------- */
.card-title-row {
  margin-bottom: 8rpx;
}

.no-margin {
  margin-bottom: 0;
}

.refresh-btn {
  font-size: 24rpx;
  color: var(--primary-d);
}

.item-text {
  display: flex;
  flex-direction: column;
}

.item-title {
  font-size: 30rpx;
  color: var(--text-1);
}

.item-desc {
  margin-top: 4rpx;
  font-size: 22rpx;
  color: var(--text-3);
  line-height: 1.6;
}

.perm-right {
  display: flex;
  align-items: center;
  gap: 16rpx;
}

.setting-btn {
  padding: 10rpx 24rpx;
  border-radius: var(--radius-full);
  background: var(--primary-l);
  font-size: 24rpx;
  color: var(--primary-d);
}

.setting-btn:active {
  opacity: 0.8;
}

.perm-tip {
  display: block;
  margin-top: 20rpx;
  font-size: 22rpx;
  color: var(--text-3);
  line-height: 1.7;
}

/* ---------- 可见范围 ---------- */
.scope-note {
  display: block;
  margin: -12rpx 0 16rpx;
  font-size: 24rpx;
  color: var(--text-3);
}

.scope-item {
  display: flex;
  align-items: center;
  gap: 20rpx;
  padding: 24rpx 0;
  border-bottom: 2rpx solid var(--divider);
}

.scope-item:last-child {
  border-bottom: none;
}

.scope-radio {
  width: 40rpx;
  height: 40rpx;
  flex-shrink: 0;
  border-radius: 50%;
  border: 3rpx solid var(--border);
  display: flex;
  align-items: center;
  justify-content: center;
}

.scope-radio.active {
  border-color: var(--primary);
}

.radio-dot {
  width: 22rpx;
  height: 22rpx;
  border-radius: 50%;
  background: var(--primary);
}

/* ---------- 数据管理 ---------- */
.list-item-icon.danger {
  background: var(--danger-l);
}

.danger-text {
  color: var(--danger);
}

/* ---------- 提示 ---------- */
.tip-card {
  margin-bottom: 48rpx;
}

.tip-title {
  display: block;
  font-size: 28rpx;
  font-weight: 600;
  color: var(--text-1);
  margin-bottom: 8rpx;
}

.register-page {
  min-height: 100vh;
  padding: 80rpx 64rpx 64rpx;
  background: linear-gradient(180deg, #f4efe6 0%, #faf7f1 100%);
}

/* ---------- 标题 ---------- */
.reg-header {
  margin-bottom: 56rpx;
  display: flex;
  flex-direction: column;
}

.reg-title {
  font-size: 56rpx;
  font-weight: 700;
  color: #2f3a2f;
}

.reg-sub {
  margin-top: 12rpx;
  font-size: 28rpx;
  color: var(--text-2);
}

/* ---------- ① 角色选择 ---------- */
.role-section {
  margin-bottom: 40rpx;
}

.role-label {
  display: block;
  margin-bottom: 20rpx;
  padding-left: 8rpx;
  font-size: 30rpx;
  font-weight: 500;
  color: #2f3a2f;
}

.role-grid {
  display: flex;
  gap: 24rpx;
}

.role-card {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8rpx;
  padding: 32rpx 16rpx;
  background: rgba(255, 255, 255, 0.85);
  border: 4rpx solid transparent;
  border-radius: 32rpx;
  box-shadow: 0 4rpx 16rpx rgba(0, 0, 0, 0.04);
  transition: all 0.25s ease;
}

.role-card.active {
  background: rgba(143, 166, 142, 0.15);
  border-color: var(--primary);
}

.role-icon {
  font-size: 56rpx;
  line-height: 1.2;
}

.role-name {
  font-size: 32rpx;
  font-weight: 600;
  color: #2f3a2f;
}

.role-desc {
  font-size: 24rpx;
  color: var(--text-2);
  text-align: center;
}

/* ---------- ② 表单 ---------- */
.field-group {
  margin-bottom: 36rpx;
}

.field-label {
  display: block;
  margin-bottom: 18rpx;
  padding-left: 8rpx;
  font-size: 30rpx;
  font-weight: 500;
  color: #2f3a2f;
}

.input-box {
  display: flex;
  align-items: center;
  gap: 20rpx;
  padding: 26rpx 36rpx;
  background: rgba(255, 255, 255, 0.9);
  border: 2rpx solid rgba(143, 166, 142, 0.15);
  border-radius: 36rpx;
  box-shadow: 0 4rpx 16rpx rgba(0, 0, 0, 0.04);
}

.input-icon {
  font-size: 36rpx;
  line-height: 1;
}

.field-input {
  flex: 1;
  min-width: 0;
  font-size: 32rpx;
  color: #2f3a2f;
}

.field-ph {
  color: var(--text-3);
}

.code-wrapper {
  display: flex;
  gap: 20rpx;
  align-items: center;
}

.flex-1 {
  flex: 1;
}

.code-btn {
  min-width: 200rpx;
  padding: 28rpx 32rpx;
  background: rgba(143, 166, 142, 0.12);
  border: 2rpx solid rgba(143, 166, 142, 0.2);
  border-radius: 36rpx;
  font-size: 28rpx;
  color: var(--primary-d);
  text-align: center;
  white-space: nowrap;
}

.code-btn.disabled {
  background: rgba(125, 116, 107, 0.08);
  border-color: transparent;
  color: var(--text-3);
}

/* ---------- ④ 提交 ---------- */
.reg-btn {
  width: 100%;
  margin-top: 48rpx;
  padding: 34rpx 0;
  background: linear-gradient(135deg, #8fa68e, #9db89c);
  border-radius: 36rpx;
  font-size: 34rpx;
  font-weight: 600;
  color: #ffffff;
  letter-spacing: 4rpx;
  text-align: center;
  box-shadow: 0 12rpx 40rpx rgba(143, 166, 142, 0.25);
}

.reg-btn:active {
  opacity: 0.9;
  transform: scale(0.98);
}

.disabled-btn {
  opacity: 0.5;
  box-shadow: none;
}

/* ---------- ⑤ 协议 ---------- */
.agreement-check-area {
  margin-top: 40rpx;
  padding: 28rpx;
  background: rgba(255, 255, 255, 0.6);
  border-radius: 28rpx;
}

.check-row {
  display: flex;
  align-items: center;
  gap: 16rpx;
}

.checkbox {
  width: 40rpx;
  height: 40rpx;
  flex-shrink: 0;
  border: 3rpx solid var(--primary);
  border-radius: 20rpx;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 24rpx;
  color: #ffffff;
}

.checkbox.checked {
  background: var(--primary);
}

.check-text {
  flex: 1;
  font-size: 26rpx;
  color: #2f3a2f;
}

/* ---------- 去登录 ---------- */
.login-hint {
  margin-top: 40rpx;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8rpx;
  font-size: 28rpx;
  color: var(--text-2);
}

.link-blue {
  font-size: 28rpx;
  font-weight: 500;
  color: var(--primary-d);
}

.settings-page {
  min-height: 100vh;
  padding: 32rpx 32rpx 64rpx;
  background: linear-gradient(180deg, #f4efe6 0%, #f5f0e6 100%);
}

/* ---------- 大字模式 Hero ---------- */
.elder-hero {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 36rpx 32rpx;
  margin-bottom: 40rpx;
  background: linear-gradient(135deg, #8fa68e 0%, #a8c4a7 100%);
  border-radius: var(--radius-lg);
  box-shadow: 0 12rpx 40rpx rgba(143, 166, 142, 0.25);
}

.elder-hero-left {
  display: flex;
  align-items: center;
  gap: 24rpx;
  flex: 1;
}

.elder-hero-icon {
  font-size: 56rpx;
  line-height: 1;
}

.elder-hero-text {
  display: flex;
  flex-direction: column;
  gap: 6rpx;
}

.elder-hero-title {
  font-size: 38rpx;
  font-weight: 700;
  color: #ffffff;
}

.elder-hero-desc {
  font-size: 24rpx;
  color: rgba(255, 255, 255, 0.85);
}

.hero-switch {
  width: 104rpx;
  height: 56rpx;
  padding: 4rpx;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  background: rgba(255, 255, 255, 0.3);
  border-radius: 28rpx;
  transition: background 0.2s ease;
}

.hero-switch.on {
  background: rgba(255, 255, 255, 0.9);
}

.hero-switch-knob {
  width: 48rpx;
  height: 48rpx;
  background: #ffffff;
  border-radius: 50%;
  box-shadow: 0 2rpx 8rpx rgba(0, 0, 0, 0.15);
  transition: transform 0.2s ease;
}

.hero-switch.on .hero-switch-knob {
  transform: translateX(48rpx);
  background: var(--primary-d);
}

/* ---------- 分组 ---------- */
.group {
  margin-bottom: 40rpx;
}

.group-title {
  display: block;
  margin-bottom: 16rpx;
  padding-left: 16rpx;
  font-size: 26rpx;
  font-weight: 600;
  color: var(--text-2);
  letter-spacing: 2rpx;
}

.group-card {
  background: var(--surface);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow);
  padding: 0 32rpx;
}

.setting-item {
  display: flex;
  align-items: center;
  gap: 24rpx;
  padding: 30rpx 0;
  border-bottom: 2rpx solid var(--divider);
}

.setting-item.last,
.setting-item:last-child {
  border-bottom: none;
}

.setting-item:active {
  opacity: 0.7;
}

.setting-icon-wrapper {
  width: 68rpx;
  height: 68rpx;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 32rpx;
  background: var(--primary-l);
  border-radius: 20rpx;
}

.setting-text {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 4rpx;
}

.setting-label {
  font-size: 32rpx;
  color: var(--text-1);
}

.setting-desc {
  font-size: 22rpx;
  color: var(--text-2);
}

.setting-right {
  display: flex;
  align-items: center;
  gap: 12rpx;
}

.setting-value {
  font-size: 28rpx;
  color: var(--text-2);
}

.setting-arrow {
  font-size: 40rpx;
  color: var(--text-3);
  line-height: 1;
}

/* 开关 */
.switch {
  width: 88rpx;
  height: 48rpx;
  padding: 4rpx;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  background: rgba(125, 116, 107, 0.2);
  border-radius: 24rpx;
  transition: background 0.2s ease;
}

.switch.on {
  background: var(--primary);
}

.switch-knob {
  width: 40rpx;
  height: 40rpx;
  background: #ffffff;
  border-radius: 50%;
  transition: transform 0.2s ease;
}

.switch.on .switch-knob {
  transform: translateX(40rpx);
}

/* ---------- 底部操作 ---------- */
.footer-actions {
  display: flex;
  flex-direction: column;
  gap: 20rpx;
  margin-top: 48rpx;
}

.footer-btn {
  padding: 30rpx 0;
  background: var(--surface);
  border-radius: var(--radius);
  font-size: 30rpx;
  color: var(--text-1);
  text-align: center;
  box-shadow: var(--shadow);
}

.footer-btn.danger {
  color: var(--danger);
}

.footer-btn:active {
  opacity: 0.85;
}

.version-text {
  display: block;
  margin-top: 40rpx;
  text-align: center;
  font-size: 24rpx;
  color: var(--text-3);
}

/* ---------- 选择弹窗 ---------- */
.modal-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 100;
  display: flex;
  align-items: flex-end;
  background: rgba(0, 0, 0, 0.45);
}

.select-box {
  width: 100%;
  padding: 32rpx 32rpx calc(32rpx + env(safe-area-inset-bottom));
  background: var(--surface);
  border-radius: 32rpx 32rpx 0 0;
}

.select-title {
  display: block;
  margin-bottom: 24rpx;
  text-align: center;
  font-size: 32rpx;
  font-weight: 600;
  color: var(--text-1);
}

.select-option {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 30rpx 24rpx;
  border-radius: 20rpx;
  font-size: 30rpx;
  color: var(--text-1);
}

.select-option.active {
  background: var(--primary-l);
  color: var(--primary-d);
  font-weight: 600;
}

/* ---------- 大字模式增强 ---------- */
.elder-mode .setting-label {
  font-size: 44rpx;
}

.elder-mode .setting-desc {
  font-size: 30rpx;
}

.elder-mode .setting-item {
  padding: 40rpx 0;
}

.elder-mode .setting-icon-wrapper {
  width: 88rpx;
  height: 88rpx;
  font-size: 42rpx;
}

.elder-mode .group-title {
  font-size: 34rpx;
}

.elder-mode .switch {
  width: 112rpx;
  height: 60rpx;
}

.elder-mode .switch.on .switch-knob {
  transform: translateX(52rpx);
}

.page-inner {
  padding: 24rpx;
}

/* ---------- 主开关 ---------- */
.master-card {
  border-left: 8rpx solid var(--text-3);
}

.master-card.on {
  border-left-color: var(--primary-d);
  background: linear-gradient(135deg, var(--surface), var(--primary-l));
}

.master-head {
  display: flex;
  align-items: center;
  gap: 20rpx;
}

.master-icon {
  width: 96rpx;
  height: 96rpx;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: var(--primary-l);
  font-size: 48rpx;
}

.master-main {
  flex: 1;
  min-width: 0;
}

.master-title {
  display: block;
  font-size: 34rpx;
  font-weight: 700;
  color: var(--text-1);
}

.master-desc {
  display: block;
  margin-top: 6rpx;
  font-size: 24rpx;
  color: var(--text-2);
  line-height: 1.6;
}

.master-status {
  display: flex;
  align-items: center;
  gap: 16rpx;
  margin-top: 24rpx;
  padding-top: 20rpx;
  border-top: 2rpx solid var(--divider);
}

.status-tip {
  font-size: 24rpx;
  color: var(--text-2);
}

/* ---------- 预览 ---------- */
.preview-note {
  display: block;
  margin: -12rpx 0 20rpx;
  font-size: 24rpx;
  color: var(--text-3);
}

.preview-box {
  padding: 24rpx;
  border-radius: var(--radius);
  background: var(--bg);
  border: 2rpx dashed var(--border);
}

.preview-card {
  padding: 24rpx;
  border-radius: var(--radius);
  background: var(--surface);
  box-shadow: var(--shadow);
}

.preview-title {
  font-size: 32rpx;
  font-weight: 600;
  color: var(--text-1);
}

.preview-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20rpx 0;
  border-bottom: 2rpx solid var(--divider);
}

.preview-label {
  font-size: 28rpx;
  color: var(--text-2);
}

.preview-value {
  font-size: 28rpx;
  font-weight: 600;
  color: var(--text-1);
}

.preview-btn {
  margin-top: 24rpx;
  height: 88rpx;
  display: flex;
  align-items: center;
  justify-content: center;
